package filestore

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"golang.org/x/crypto/argon2"
)

const (
	maxFileSize    = 10 * 1024 * 1024 // 10MB
	uploadDir      = "/var/uploads"
	quotaPerUser   = 50 * 1024 * 1024 // 50MB
	tokenLength    = 32
	argonTime      = 1
	argonMemory    = 64 * 1024
	argonThreads   = 4
	argonKeyLen    = 32
)

var (
	ErrQuotaExceeded = errors.New("storage quota exceeded")
	ErrInvalidToken  = errors.New("invalid authentication token")
	ErrInvalidPath   = errors.New("invalid file path")
)

type UserSession struct {
	UserID    string
	TokenHash []byte
	Salt      []byte
	ExpiresAt time.Time
}

type FileStore struct {
	mu       sync.RWMutex
	sessions map[string]*UserSession
}

func NewFileStore() *FileStore {
	return &FileStore{
		sessions: make(map[string]*UserSession),
	}
}

func (fs *FileStore) hashToken(token []byte, salt []byte) []byte {
	return argon2.IDKey(token, salt, argonTime, argonMemory, argonThreads, argonKeyLen)
}

func (fs *FileStore) Authenticate(r *http.Request) (*UserSession, error) {
	authHeader := r.Header.Get("Authorization")
	if !strings.HasPrefix(authHeader, "Bearer ") {
		return nil, ErrInvalidToken
	}
	token := authHeader[7:]
	tokenBytes, err := hex.DecodeString(token)
	if err != nil || len(tokenBytes) != tokenLength {
		return nil, ErrInvalidToken
	}

	fs.mu.RLock()
	defer fs.mu.RUnlock()

	for _, session := range fs.sessions {
		if time.Now().After(session.ExpiresAt) {
			continue
		}
		computedHash := fs.hashToken(tokenBytes, session.Salt)
		if subtle.ConstantTimeCompare(computedHash, session.TokenHash) == 1 {
			return session, nil
		}
	}
	return nil, ErrInvalidToken
}

func (fs *FileStore) sanitizeFilename(name string) (string, error) {
	cleaned := filepath.Clean(name)
	if strings.Contains(cleaned, "..") {
		return "", ErrInvalidPath
	}
	base := filepath.Base(cleaned)
	if base == "." || base == "/" {
		return "", ErrInvalidPath
	}
	if strings.HasPrefix(base, ".") {
		return "", ErrInvalidPath
	}
	return base, nil
}

func (fs *FileStore) getUserDir(userID string) string {
	safeID := hex.EncodeToString([]byte(userID))
	return filepath.Join(uploadDir, safeID)
}

func (fs *FileStore) checkQuota(userDir string, incomingSize int64) error {
	var totalSize int64
	entries, err := os.ReadDir(userDir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}
	for _, entry := range entries {
		info, err := entry.Info()
		if err != nil {
			continue
		}
		totalSize += info.Size()
	}
	if totalSize+incomingSize > quotaPerUser {
		return ErrQuotaExceeded
	}
	return nil
}

// validateDestination checks that the target path is safe before writing
func (fs *FileStore) validateDestination(destPath string) error {
	// Resolve any symlinks to get the real path
	dir := filepath.Dir(destPath)
	realDir, err := filepath.EvalSymlinks(dir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil // directory will be created
		}
		return err
	}
	// Ensure resolved path is still under uploadDir
	if !strings.HasPrefix(realDir, uploadDir) {
		return ErrInvalidPath
	}
	// Check if destination already exists and is a symlink
	info, err := os.Lstat(destPath)
	if err != nil {
		if os.IsNotExist(err) {
			return nil // file doesn't exist yet, safe to create
		}
		return err
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return ErrInvalidPath
	}
	return nil
}

func (fs *FileStore) HandleUpload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	session, err := fs.Authenticate(r)
	if err != nil {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxFileSize)

	filename := r.URL.Query().Get("name")
	safeName, err := fs.sanitizeFilename(filename)
	if err != nil {
		http.Error(w, "invalid filename", http.StatusBadRequest)
		return
	}

	userDir := fs.getUserDir(session.UserID)
	if err := os.MkdirAll(userDir, 0750); err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	// Read the upload into a temporary buffer to get size
	tmpFile, err := os.CreateTemp(userDir, ".upload-*")
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	tmpPath := tmpFile.Name()
	defer func() {
		tmpFile.Close()
		os.Remove(tmpPath)
	}()

	written, err := io.Copy(tmpFile, r.Body)
	if err != nil {
		http.Error(w, "upload failed", http.StatusBadRequest)
		return
	}
	tmpFile.Close()

	if err := fs.checkQuota(userDir, written); err != nil {
		http.Error(w, err.Error(), http.StatusForbidden)
		return
	}

	destPath := filepath.Join(userDir, safeName)

	// Validate the destination is safe (not a symlink, under uploadDir)
	if err := fs.validateDestination(destPath); err != nil {
		http.Error(w, "invalid destination", http.StatusBadRequest)
		return
	}

	// TOCTOU window: between validateDestination and os.Rename,
	// an attacker with local access can replace destPath with a symlink
	if err := os.Rename(tmpPath, destPath); err != nil {
		http.Error(w, "save failed", http.StatusInternalServerError)
		return
	}

	// Generate unique file ID for response
	idBytes := make([]byte, 16)
	rand.Read(idBytes)
	fileID := hex.EncodeToString(idBytes)

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	fmt.Fprintf(w, `{"id":"%s","name":"%s","size":%d}`, fileID, safeName, written)
}
